const execution = $input.first().json.execution;
const workflow = $input.first().json.workflow;

return [{
  json: {
    execution_id: execution.id,
    workflow_name: workflow.name,
    error_message: execution.error ? execution.error.message : 'Unknown runtime failure',
    error_stack: execution.error ? execution.error.stack : '',
    failed_at: new Date().toISOString(),
    step_name: 'N8N_WORKFLOW_FAILURE_ROLLBACK'
  }
}];

const item = $('Format Error Diagnostics').item.json;
return [{
  json: {
    channel: "#devops-support-alerts",
    text: `🔥 *CRITICAL: n8n Workflow Failure Detected*`,
    attachments: [{
      color: "#ef4444",
      title: `Workflow: ${item.workflow_name} (ID: ${item.execution_id})`,
      fields: [
        { title: "Error Message", value: item.error_message, short: false },
        { title: "Failed At", value: item.failed_at, short: true },
        { title: "Audit Status", value: "Logged to PostgreSQL execution_logs", short: true }
      ]
    }]
  }
}];
